#!/bin/bash set -e export ANDROID_SDK_ROOT=$HOME/android-sdk mkdir -p "$ANDROID_SDK_ROOT/cmdline-tools" cd "$ANDROID_SDK_ROOT/cmdline-tools" curl -sSL -o cmdline-tools.zip https://dl.google.com/android/repository/commandlinetools-linux-11076708_latest.zip unzip -q cmdline-tools.zip mv cmdline-tools latest rm cmdline-tools.zip export PATH="$PATH:$ANDROID_SDK_ROOT/cmdline-tools/latest/bin:$ANDROID_SDK_ROOT/platform-tools" yes | sdkmanager --licenses > /dev/null sdkmanager "platform-tools" "platforms;android-34" "build-tools;34.0.0" { echo "export ANDROID_SDK_ROOT=$ANDROID_SDK_ROOT" echo "export PATH=\$PATH:\$ANDROID_SDK_ROOT/cmdline-tools/latest/bin:\$ANDROID_SDK_ROOT/platform-tools" } >> ~/.bashrc echo "Android SDK setup complete."
